<template>
  <q-dialog v-model="swDialog" persistent @show="onShow" @hide="onHide">
    <q-card
      id="dialog-card"
      ref="resizable"
      class="resizable"
      :style="{
        width: isResizeAble
          ? widths + 'px !important'
          : width + 'px !important',
        height: height + 'px !important',
        maxHeight: '90vh',
        transform: `translate(${left}px, ${top}px)`,
      }"
      @mousedown="startAction"
    >
      <q-toolbar
        class="text-white secondary-toolbar draggable-toolbar"
        :class="draggable ? 'cursor-move' : ''"
      >
        <q-toolbar-title>
          <span class="text-weight-bold">{{ title }}</span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" class="text-white" v-close-popup />
      </q-toolbar>
      <div class="dialog-content">
        <slot></slot>
      </div>
    </q-card>
  </q-dialog>
</template>

<script>
export default {
  name: 'dialogDraggable',
  props: {
    draggable: { type: Boolean, default: true },
    modelDialog: { type: Boolean, default: false },
    title: { type: String, default: 'Title' },
    width: { type: Number, default: 650 },
    isResizeAble: { type: Boolean, default: false },
  },
  windowWidth: window.innerWidth,
  data() {
    return {
      swDialog: false,
      target: null,
      nodeDragg: null,
      isResizing: false,
      isDragging: false,
      startX: 0,
      startY: 0,
      startWidth: 0,
      startHeight: 0,
      startLeft: 0,
      startTop: 0,
      widths: window.innerWidth / 1.4,
      height: window.innerHeight / 1.11,
      left: 0,
      top: 0,
    };
  },
  watch: {
    modelDialog(val) {
      this.swDialog = val;
    },
  },
  mounted() {
    window.addEventListener('resize', this.onWindowResize);
  },
  methods: {
    startAction(event) {
      if (!this.draggable) return;
      const cardEl = this.$refs.resizable?.$el;
      if (!cardEl) return;
      const cardRect = cardEl.getBoundingClientRect();
      const isOnResizeCorner =
        event.clientX - cardRect.left >= cardRect.width - 20 &&
        event.clientY - cardRect.top >= cardRect.height - 20;
      if (!isOnResizeCorner) return;
      event.preventDefault();
      this.startX = event.clientX;
      this.startY = event.clientY;
      this.startLeft = this.left;
      this.startTop = this.top;
      this.startWidth = this.widths;
      this.startHeight = this.height;
      this.isResizing = true;
      document.addEventListener('mousemove', this.moveOrResize);
      document.addEventListener('mouseup', this.stopAction);
    },
    moveOrResize(event) {
      if (this.isResizing) {
        this.resize(event);
      } else if (this.isDragging) {
        this.drag(event);
      }
    },
    onWindowResize(event) {
      if (this.isResizeAble) {
        this.widths =
          this.widths - (this.$options.windowWidth - window.innerWidth);
        this.$options.windowWidth = window.innerWidth;
      }
    },
    resize(event) {
      if (!this.isResizeAble) return;
      if (this.isResizing) {
        const cardElement = this.$refs.resizable.$el;
        const rect = cardElement.getBoundingClientRect();
        const deltaY = event.clientY - this.startY;
        const deltaX = event.clientX - this.startX;
        this.widths = Math.max(50, this.startWidth + deltaX);
        this.height = Math.max(50, this.startHeight + deltaY * 2);
      }
    },
    drag(event) {
      if (this.isDragging) {
        const deltaX = event.clientX - this.startX;
        const deltaY = event.clientY - this.startY;
        this.left = this.startLeft + deltaX;
        this.top = this.startTop + deltaY;
      }
    },
    stopAction() {
      this.isResizing = false;
      this.isDragging = false;
      document.removeEventListener('mousemove', this.moveOrResize);
      document.removeEventListener('mouseup', this.stopAction);
    },
    onShow() {
      let dialogElements = document.getElementsByClassName('q-dialog');
      this.target = dialogElements[0].querySelector('.q-card');
      this.nodeDragg = this.target.querySelector('.draggable-toolbar');
      if (this.draggable) {
        this.nodeDragg.addEventListener('mousedown', this.onGrab);
      }
      this.$emit('onShow');
    },
    onHide() {
      if (this.draggable) {
        this.nodeDragg.removeEventListener('mousedown', this.onGrab);
      }
      this.left = 0;
      this.top = 0;
      this.widths = window.innerWidth / 1.4;
      this.height = window.innerHeight / 1.11;
      this.$emit('onHide');
    },
    onGrab(event) {
      this.isDragging = true;
      this.startX = event.clientX;
      this.startY = event.clientY;
      this.startLeft = this.left;
      this.startTop = this.top;
      document.addEventListener('mousemove', this.moveOrResize);
      document.addEventListener('mouseup', this.stopAction);
    },
  },
};
</script>

<style scoped>
.cursor-move {
  cursor: move;
}
.resizable {
  resize: both;
  overflow: hidden;
  border: 1px solid #ccc;
  display: flex;
  flex-direction: column;
}
.dialog-content {
  flex: 1 1 auto;
  overflow-y: auto;
  min-height: 0;
}
</style>
